const W_SEARCH  = 0.25;
const W_HIRING  = 0.25;
const W_DISCUSS = 0.2;
const W_NEWS    = 0.15;
const W_SOCIAL  = 0.15;

const rows = $input.all().map(i => i.json);
const row = rows[0];

if (!row) {
  throw new Error('No trend_history row found for today. Run Trend Discovery first.');
}

const courses = typeof row.courses === 'string' ? JSON.parse(row.courses) : row.courses;

if (!Array.isArray(courses) || courses.length === 0) {
  throw new Error('trend_history row found, but courses array is empty. Run Trend Discovery first.');
}

function minMax(arr, key) {
  const vals = arr.map(c => Number(c[key]) || 0);
  const min = Math.min(...vals), max = Math.max(...vals);
  return v => (max === min ? 0 : ((Number(v) || 0) - min) / (max - min));
}
const normSearch  = minMax(courses, 'search_volume');
const normHiring  = minMax(courses, 'hiring_demand');
const normDiscuss = minMax(courses, 'discussion_count');
const normNews    = minMax(courses, 'mentions');
const normSocial  = minMax(courses, 'popularity_score');

const scored = courses.map(c => {
  const score = 100 * (
    W_SEARCH  * normSearch(c.search_volume) +
    W_HIRING  * normHiring(c.hiring_demand) +
    W_DISCUSS * normDiscuss(c.discussion_count) +
    W_NEWS    * normNews(c.mentions) +
    W_SOCIAL  * normSocial(c.popularity_score)
  );
  return { ...c, trend_score: Math.round(score * 100) / 100 };
});

scored.sort((a, b) => b.trend_score - a.trend_score);
const top10 = scored.slice(0, 10).map((c, idx) => ({ ...c, rank_position: idx + 1 }));
const top10Keys = new Set(top10.map(c => c.normalized_name));
const updatedCourses = scored.map(c => top10Keys.has(c.normalized_name)
  ? top10.find(t => t.normalized_name === c.normalized_name)
  : c
);

return [{ json: { row_id: row.id, updated_courses: updatedCourses, top10: top10 } }];

const allScored = $('Compute Trend Score').item.json.updated_courses;
const coveredRows = $input.first().json;
const coveredNames = new Set((Array.isArray(coveredRows) ? coveredRows : []).map(function(r) { return (r.name || '').toLowerCase().trim(); }));

const SEARCH_POOL_SIZE = 20;
const MIN_REQUIRED = 6;

const pool = allScored.slice(0, SEARCH_POOL_SIZE);
const uncovered = pool.filter(function(c) { return !coveredNames.has((c.course_name || '').toLowerCase().trim()); });
const pick = uncovered.slice(0, MIN_REQUIRED);

const shortfallWarning = pick.length < MIN_REQUIRED
  ? ('Only ' + pick.length + ' uncovered courses found in top ' + SEARCH_POOL_SIZE + ' today, needed ' + MIN_REQUIRED + '.')
  : null;
if (shortfallWarning) { console.log('WARNING: ' + shortfallWarning); }

return pick.map(function(c, idx) { return { json: {
  course_name: c.course_name,
  normalized_name: c.normalized_name,
  trend_score: c.trend_score,
  rank_position: idx + 1,
  shortfall_warning: shortfallWarning
} }; });
